$c=Get-CimInstance Win32_Processor|Select-Object -First 1;$b=Get-CimInstance Win32_BaseBoard|Select-Object -First 1;$m=@(Get-CimInstance Win32_PhysicalMemory);$a=@(Get-CimInstance Win32_PhysicalMemoryArray|Where-Object{$_.Use -eq 3});$v=@(Get-CimInstance Win32_VideoController);$r=@(Get-ItemProperty 'HKLM:\SYSTEM\ControlSet001\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}\0*' -ErrorAction SilentlyContinue|Where-Object{$_.'HardwareInformation.qwMemorySize'}|ForEach-Object{$q=$_.'HardwareInformation.qwMemorySize';if($q -is [array]){$q=[BitConverter]::ToUInt64([byte[]]$q,0)};@{n=$_.DriverDesc;b=[uint64]$q}});$e=Get-CimInstance Win32_SystemEnclosure|Select-Object -First 1;$d=Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'";[ordered]@{apv=1;cpu="$($c.Name)".Trim();cores=$c.NumberOfCores;threads=$c.NumberOfLogicalProcessors;board="$($b.Manufacturer) $($b.Product)".Trim();ram=@($m|ForEach-Object{@{gb=[math]::Round($_.Capacity/1GB);mhz=$_.Speed;t=$_.SMBIOSMemoryType;ff=$_.FormFactor}});slots=($a|Measure-Object MemoryDevices -Sum).Sum;maxgb=[math]::Round(($a|Measure-Object MaxCapacity -Sum).Sum/1MB);gpu=@($v|ForEach-Object{@{n=$_.Name;b=$_.AdapterRAM}});vram=$r;chassis=@($e.ChassisTypes);battery=[bool](Get-CimInstance Win32_Battery);os=(Get-CimInstance Win32_OperatingSystem).Caption;freegb=[math]::Round($d.FreeSpace/1GB)}|ConvertTo-Json -Compress -Depth 4|Set-Clipboard;'Done! Your results are copied. Go back to the web page and paste them in the box.'
